import React from 'react';

const shimmerStyle = {
    background: 'linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 37%, #f0f0f0 63%)',
    backgroundSize: '400% 100%',
    animation: 'shimmer 1.4s ease infinite',
    borderRadius: '8px',
    marginBottom: '12px',
};

const shimmerKeyframes = `
@keyframes shimmer {
    0% { background-position: -400px 0; }
    100% { background-position: 400px 0; }
}
`;

const Shimmer = () => {
    const shimmerCards = Array(6).fill(0);

    return (
        <>
            <style>{shimmerKeyframes}</style>
            <div className="container mt-4">
                <div className="row g-4">
                    {shimmerCards.map((_, index) => (
                        <div className="col-md-4" key={index}>
                            <div style={{
                                backgroundColor: '#f6f7f8',
                                borderRadius: '16px',
                                padding: '20px',
                                boxShadow: '0 0 10px rgba(0, 0, 0, 0.1)'
                            }}>
                                <div style={{ ...shimmerStyle, height: '180px', width: '100%' }}></div>
                                <div style={{ ...shimmerStyle, height: '20px', width: '60%' }}></div>
                                <div style={{ ...shimmerStyle, height: '16px', width: '40%' }}></div>
                                <div style={{ ...shimmerStyle, height: '24px', width: '30%' }}></div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </>
    );
};

export default Shimmer;
